const DEFAULTS={name:'Jackx Cafe',tagline:"coffee's got a new address",logo:'',accent:'#f05a28',bg:'#f9eadb',text:'#4b2017',card:'#fff8f0',font:'Cairo',size:'16px',radius:'999px',links:[{icon:'▤',title:'MENU',detail:'شوف المنيو الكامل',url:'#menu'},{icon:'T',title:'FEEDBACK',detail:'شاركنا رأيك',url:'#feedback'},{icon:'⌖',title:'Google Maps',detail:'افتح الموقع على الخريطة',url:'https://maps.google.com'},{icon:'f',title:'Facebook',detail:'تابعنا على فيسبوك',url:'#facebook'},{icon:'◎',title:'Instagram',detail:'شوف صورنا وأخبارنا',url:'#instagram'}],socials:[['◎','#instagram'],['♪','#tiktok'],['f','#facebook'],['◔','https://wa.me/201000000000']]};
const getData=()=>{try{return {...DEFAULTS,...JSON.parse(localStorage.getItem('qr-caffe-data')||'{}')}}catch{return DEFAULTS}};const setData=d=>localStorage.setItem('qr-caffe-data',JSON.stringify(d));
function applyTheme(d,root=document.documentElement){root.style.setProperty('--accent',d.accent);root.style.setProperty('--bg',d.bg);root.style.setProperty('--text',d.text);root.style.setProperty('--card',d.card);root.style.setProperty('--font',`${d.font},Arial,sans-serif`);root.style.setProperty('--size',d.size);root.style.setProperty('--radius',d.radius)}
function initClient(){const d=getData();applyTheme(d);document.getElementById('clientName').textContent=d.name;document.getElementById('clientTagline').textContent=d.tagline;const img=document.getElementById('clientLogo');if(d.logo){img.src=d.logo;img.style.display='block';document.getElementById('logoFallback').style.display='none'}document.getElementById('socialRow').innerHTML=d.socials.map(([icon,url])=>`<a href="${url}" aria-label="رابط تواصل">${icon}</a>`).join('');document.getElementById('linkStack').innerHTML=d.links.map(l=>`<a class="link-card" href="${l.url}" target="_blank"><span class="link-icon">${l.icon}</span><span class="link-copy"><span class="link-title">${l.title}</span><span class="link-detail">${l.detail}</span></span><span class="link-more">⋮</span></a>`).join('')}
function initAdmin(){const d=getData();const ids=['name','tagline','accent','bg','text','card','font','size','radius'];ids.forEach(k=>{const el=document.getElementById(k+'Input');if(el)el.value=d[k]});renderEditors(d.links);ids.forEach(k=>document.getElementById(k+'Input').addEventListener('input',refresh));document.getElementById('logoInput').addEventListener('change',e=>{const f=e.target.files[0];if(f){const r=new FileReader();r.onload=()=>{window.adminLogo=r.result;refresh()};r.readAsDataURL(f)}});document.getElementById('saveBtn').addEventListener('click',()=>{const next=collect();setData(next);document.getElementById('saveMessage').textContent='تم حفظ التخصيص بنجاح';document.getElementById('previewFrame').contentWindow.location.reload();setTimeout(()=>document.getElementById('saveMessage').textContent='',2500)});document.getElementById('addLink').addEventListener('click',()=>{d.links.push({icon:'★',title:'رابط جديد',detail:'اكتب وصف الرابط',url:'#'});renderEditors(d.links)});function collect(){return {...getData(),name:val('name'),tagline:val('tagline'),accent:val('accent'),bg:val('bg'),text:val('text'),card:val('card'),font:val('font'),size:val('size'),radius:val('radius'),logo:window.adminLogo||getData().logo,links:[...document.querySelectorAll('.link-edit')].map(row=>({icon:row.querySelector('[data-k=icon]').value,title:row.querySelector('[data-k=title]').value,detail:row.querySelector('[data-k=detail]').value,url:row.querySelector('[data-k=url]').value}))}}function val(k){return document.getElementById(k+'Input').value}function refresh(){const next=collect();applyTheme(next);const frame=document.getElementById('previewFrame');frame.contentWindow.postMessage({type:'preview',data:next},'*')}window.addEventListener('message',e=>{})}
function renderEditors(links){document.getElementById('linksEditor').innerHTML=links.map((l,i)=>`<div class="link-edit"><input data-k="icon" value="${l.icon}" aria-label="أيقونة الرابط"><input data-k="title" value="${l.title}" aria-label="عنوان الرابط"><input data-k="detail" value="${l.detail}" aria-label="وصف الرابط"><input data-k="url" value="${l.url}" aria-label="الرابط"><button class="delete-link" data-i="${i}" aria-label="حذف الرابط">×</button></div>`).join('');document.querySelectorAll('.delete-link').forEach(b=>b.addEventListener('click',()=>{b.parentElement.remove()}));}
window.addEventListener('message',e=>{if(e.data?.type==='preview'){applyTheme(e.data.data);const d=e.data.data;document.getElementById('clientName').textContent=d.name;document.getElementById('clientTagline').textContent=d.tagline;document.getElementById('linkStack').innerHTML=d.links.map(l=>`<a class="link-card" href="${l.url}"><span class="link-icon">${l.icon}</span><span class="link-copy"><span class="link-title">${l.title}</span><span class="link-detail">${l.detail}</span></span><span class="link-more">⋮</span></a>`).join('')}});
window.QR={initClient,initAdmin};
